2	import assert from 'node:assert/strict';
3	import { readFileSync } from 'node:fs';
4	import { createHash } from 'node:crypto';
5	import { stateAfter } from './src/queue.ts';
6	import { statusCell, compactStatus, display } from './src/queue-view.ts';
7	const expected = process.argv[2];
8	assert.ok(expected, 'Pass the selected PLAR delivery path');
9	const state = stateAfter('ok');
10	assert.equal(state, 'succeeded');
11	const consumers = [statusCell(state), compactStatus(state)];
12	for (const consumer of consumers) {
13	  assert.equal(consumer.path, expected);
14	  assert.equal(consumer.frames, 1);
15	}
16	const data = readFileSync(new URL(expected, import.meta.url));
17	assert.equal(data.subarray(0,8).toString('hex'), '89504e470d0a1a0a');
18	assert.deepEqual([data.readUInt32BE(16), data.readUInt32BE(20)], display.cell);
19	assert.equal(display.filter, 'nearest');
20	const hash = bytes => createHash('sha256').update(bytes).digest('hex');
21	console.log(JSON.stringify({state, consumers, display, file: expected,
22	  sha256: hash(data), sources: Object.fromEntries(['src/queue.ts','src/queue-view.ts'].map(
